const patients = $('📋 Get Patients').all().map(i => i.json);
const patientMap = {};
for (const p of patients) { patientMap[p.PatNum] = p; }

const results = [];
for (const item of items) {
  const d = item.json;
  if (d.ProcStatus !== 'TP') continue;
  if (d.PipelineStatus === 'Recovered') continue;

  const days = parseInt(d.DaysUnscheduled, 10) || 0;
  const fee = parseFloat(d.ProcFee) || 0;
  const stage = (d.FollowUpStage || '').trim();
  const patient = patientMap[d.PatNum] || {};

  let action = 'none';
  if (stage === 'Escalated') {
    action = 'none';
  } else if (stage === '' && days >= 3) {
    action = 'send_1st';
  } else if (stage === '1st email sent' && days >= 14) {
    action = 'send_2nd';
  } else if (stage === '2nd email sent' && days >= 30) {
    action = 'send_3rd';
  } else if (stage === '3rd email sent' && days >= 45) {
    action = 'escalate';
  }
  if (action === 'none') continue;

  results.push({ json: {
    ...d,
    days, fee, action,
    Email: patient.Email || '',
    WirelessPhone: patient.WirelessPhone || '',
    Provider: patient.Provider || '',
    FName: patient.FName || '',
    LName: patient.LName || ''
  }});
}
return results;

