const rows = items.map(i => i.json);
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7*24*60*60*1000);

let recoveredValue = 0, recoveredCount = 0;
let sittingValue = 0, sittingCount = 0;
let activeCount = 0, escalatedCount = 0;
const wins = [];

for (const r of rows) {
  const fee = parseFloat(r.ProcFee) || 0;
  if (r.PipelineStatus === 'Recovered') {
    const lastContact = r.LastContactDate ? new Date(r.LastContactDate) : null;
    if (lastContact && lastContact >= sevenDaysAgo) {
      recoveredValue += fee;
      recoveredCount += 1;
      wins.push(`${r.Patient} — ${r.Description} — $${fee}`);
    }
  }
  if (r.ProcStatus === 'TP') {
    sittingValue += fee;
    sittingCount += 1;
    if (r.FollowUpStage === 'Escalated') escalatedCount += 1;
    else activeCount += 1;
  }
}

const summaryText = `Recovered this week: $${recoveredValue} (${recoveredCount} treatment plans)\nSitting unscheduled: $${sittingValue} (${sittingCount} treatment plans)\nIn active follow-up: ${activeCount}\nNeeds a personal call: ${escalatedCount}\n\nThis week's wins:\n${wins.length ? wins.join('\n') : 'None this week'}`;

return [{ json: { recoveredValue, recoveredCount, sittingValue, sittingCount, activeCount, escalatedCount, wins, summaryText } }];
